function countElements(nums) {
  let count = 0;
  for (let i = 0; i < nums.length; i++) {
    let below = false;
    let above = false;
    for (let j = 0; j < nums.length; j++) {
      if (nums[j] < nums[i]) below = true;
      if (nums[j] > nums[i]) above = true;
    }
    if (below && above) count++;
  }
  return count;
}

