function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const span = rand() < 0.5 ? 100000 : pick(1, 20);
    return [Array.from({ length: 100 }, () => pick(-span, span))];
  }
  const length = pick(1, 8);
  const span = pick(0, 4);
  return [Array.from({ length }, () => pick(-span, span))];
}
